class SegmentTree {
  constructor(arr) {
    this.n = arr.length;
    this.tree = new Array(4 * this.n).fill(0);
    this.build(arr, 1, 0, this.n - 1);
  }

  build(arr, node, start, end) {
    if (start === end) {
      this.tree[node] = arr[start];
      return;
    }
    const mid = Math.floor((start + end) / 2);
    this.build(arr, 2 * node, start, mid);
    this.build(arr, 2 * node + 1, mid + 1, end);
    // combine children
    this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
  }

  update(node, start, end, idx, val) {
    if (start === end) {
      this.tree[node] = val;
      return;
    }
    const mid = Math.floor((start + end) / 2);
    if (idx <= mid) {
      this.update(2 * node, start, mid, idx, val);
    } else {
      this.update(2 * node + 1, mid + 1, end, idx, val);
    }
    // recompute from updated children
    this.tree[node] = this.tree[2 * node] + this.tree[2 * node + 1];
  }

  query(node, start, end, l, r) {
    // fully outside
    if (r < start || end < l) return 0;
    // fully inside
    if (l <= start && end <= r) return this.tree[node];
    // partial overlap - split
    const mid = Math.floor((start + end) / 2);
    const leftSum = this.query(2 * node, start, mid, l, r);
    const rightSum = this.query(2 * node + 1, mid + 1, end, l, r);
    return leftSum + rightSum;
  }

  // public wrappers
  pointUpdate(idx, val) { this.update(1, 0, this.n - 1, idx, val); }
  rangeQuery(l, r) { return this.query(1, 0, this.n - 1, l, r); }
}
